import { readFileSync } from 'node:fs';

export interface Formula {
  variables: number;
  clauses: number[][];
}
export type Model = boolean[];
export class InputError extends Error {}
export const wellFormedNumber = (text: string): boolean => /^(?:0|[1-9][0-9]{0,5})$/.test(text);

export function readDimacs(filename: string): Formula {
  const clauses: number[][] = [];
  let header: { variables: number; count: number } | undefined;
  let pending: number[] = [];
  const lines = readFileSync(filename, 'ascii').split('\n');
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    const n = index + 1;
    if (line.startsWith('c') || line.trim() === '') continue;
    const tokens = line.trim().split(/ +/);
    if (tokens[0] === 'p') {
      if (header !== undefined) throw new InputError(`duplicate header at line ${n}`);
      if (
        tokens.length !== 4 ||
        tokens[1] !== 'cnf' ||
        !wellFormedNumber(tokens[2]) ||
        !wellFormedNumber(tokens[3])
      ) {
        throw new InputError(`bad header at line ${n}`);
      }
      header = { variables: Number(tokens[2]), count: Number(tokens[3]) };
      continue;
    }
    if (header === undefined) throw new InputError('missing header');
    for (const token of tokens) {
      if (!/^(?:0|-?[1-9][0-9]{0,5})$/.test(token)) {
        throw new InputError(`bad token ${token} at line ${n}`);
      }
      const literal = Number(token);
      if (Math.abs(literal) > header.variables) {
        throw new InputError(`literal out of range ${token} at line ${n}`);
      }
      if (literal === 0) {
        clauses.push(pending);
        pending = [];
      } else pending.push(literal);
    }
  }
  if (header === undefined) throw new InputError('missing header');
  if (pending.length > 0) throw new InputError('unterminated clause');
  if (clauses.length !== header.count) {
    throw new InputError(`clause count mismatch header=${header.count} found=${clauses.length}`);
  }
  return { variables: header.variables, clauses };
}
export function modelLines(model: Model): string[] {
  const tokens: number[] = [];
  for (let x = 1; x < model.length; x++) tokens.push(model[x] ? x : -x);
  tokens.push(0);
  const lines: string[] = [];
  for (let i = 0; i < tokens.length; i += 10) lines.push('v ' + tokens.slice(i, i + 10).join(' '));
  return lines;
}

import type { Model } from './cnf_io.ts';

export interface SearchStatistics {
  decisions: number;
  propagations: number;
  conflicts: number;
  maxDepth: number;
}
type TrailKind = 'D' | 'F' | 'P';
interface TrailEntry {
  literal: number;
  kind: TrailKind;
}
export interface RoundResult {
  satisfiable: boolean;
  model: Model | null;
  statistics: SearchStatistics;
  events: string[];
}

class Round {
  private clauses: number[][];
  private values: number[];
  private trail: TrailEntry[] = [];
  private position = 0;
  private watches = new Map<number, number[]>();
  private depth = 0;
  private statistics: SearchStatistics = {
    decisions: 0,
    propagations: 0,
    conflicts: 0,
    maxDepth: 0,
  };
  private events: string[] = [];
  constructor(
    private variables: number,
    clauses: number[][],
  ) {
    this.clauses = clauses.map((clause) => clause.slice());
    this.values = Array(variables + 1).fill(0);
  }
  private value(literal: number): number {
    return this.values[Math.abs(literal)] * (literal > 0 ? 1 : -1);
  }
  private watch(literal: number): number[] {
    let list = this.watches.get(literal);
    if (list === undefined) {
      list = [];
      this.watches.set(literal, list);
    }
    return list;
  }
  private assign(literal: number, kind: TrailKind): void {
    this.values[Math.abs(literal)] = literal > 0 ? 1 : -1;
    this.trail.push({ literal, kind });
    this.events.push(kind + literal);
    if (kind !== 'P') this.depth++;
  }
  private conflict(): false {
    this.statistics.conflicts++;
    this.events.push('C');
    return false;
  }
  private initialize(): boolean {
    this.clauses.forEach((clause, i) => {
      if (clause.length >= 2) {
        this.watch(clause[0]).push(i);
        this.watch(clause[1]).push(i);
      }
    });
    for (const clause of this.clauses) {
      if (clause.length === 0 || (clause.length === 1 && this.value(clause[0]) < 0)) {
        return this.conflict();
      }
      if (clause.length === 1 && this.value(clause[0]) === 0) {
        this.assign(clause[0], 'P');
        this.statistics.propagations++;
      }
    }
    return true;
  }
  private propagate(): boolean {
    while (this.position < this.trail.length) {
      const f = -this.trail[this.position++].literal;
      const list = this.watch(f);
      let i = 0;
      while (i < list.length) {
        const number = list[i];
        const clause = this.clauses[number];
        if (clause[0] === f) [clause[0], clause[1]] = [clause[1], clause[0]];
        if (this.value(clause[0]) > 0) {
          i++;
          continue;
        }
        let replacement = 2;
        while (replacement < clause.length && this.value(clause[replacement]) < 0) replacement++;
        if (replacement < clause.length) {
          [clause[1], clause[replacement]] = [clause[replacement], clause[1]];
          list.splice(i, 1);
          this.watch(clause[1]).push(number);
          continue;
        }
        if (this.value(clause[0]) < 0) return this.conflict();
        this.assign(clause[0], 'P');
        this.statistics.propagations++;
        i++;
      }
    }
    return true;
  }
  private decide(): boolean {
    const positive: number[] = Array(this.variables + 1).fill(0);
    const negative: number[] = Array(this.variables + 1).fill(0);
    for (const clause of this.clauses) {
      if (clause.some((literal) => this.value(literal) > 0)) continue;
      for (const literal of clause) {
        if (this.value(literal) === 0) (literal > 0 ? positive : negative)[Math.abs(literal)]++;
      }
    }
    let chosen = 0;
    let count = 0;
    for (let x = 1; x <= this.variables; x++) {
      if (positive[x] > count) {
        count = positive[x];
        chosen = x;
      }
      if (negative[x] > count) {
        count = negative[x];
        chosen = -x;
      }
    }
    if (chosen === 0) return false;
    this.assign(chosen, 'D');
    this.statistics.decisions++;
    this.statistics.maxDepth = Math.max(this.statistics.maxDepth, this.depth);
    return true;
  }
  private removeLast(): TrailEntry {
    const item = this.trail.pop()!;
    this.values[Math.abs(item.literal)] = 0;
    if (item.kind !== 'P') this.depth--;
    return item;
  }
  private backtrack(): boolean {
    while (this.trail.length > 0 && this.trail[this.trail.length - 1].kind !== 'D') {
      this.removeLast();
    }
    if (this.trail.length === 0) return false;
    const decision = this.removeLast();
    this.position = this.trail.length;
    this.assign(-decision.literal, 'F');
    return true;
  }
  private finish(satisfiable: boolean): RoundResult {
    return {
      satisfiable,
      model: satisfiable ? this.values.map((value) => value > 0) : null,
      statistics: this.statistics,
      events: this.events,
    };
  }
  run(): RoundResult {
    if (!this.initialize()) return this.finish(false);
    for (;;) {
      if (!this.propagate()) {
        if (!this.backtrack()) return this.finish(false);
      } else if (!this.decide()) return this.finish(true);
    }
  }
}
export function solveRound(variables: number, clauses: number[][]): RoundResult {
  return new Round(variables, clauses).run();
}

import type { Formula, Model } from './cnf_io.ts';

export interface Graph {
  name: string;
  vertices: number;
  edges: [number, number][];
  reason: string | null;
  maximumDegree: number;
  greedy: { used: number; colors: number[] };
}
export function queens(size: number): Formula {
  const variables = size * size;
  const clauses: number[][] = [];
  for (let r = 0; r < size; r++) {
    clauses.push(Array.from({ length: size }, (_, c) => r * size + c + 1));
  }
  for (let a = 1; a <= variables; a++) {
    for (let b = a + 1; b <= variables; b++) {
      const r = Math.floor((a - 1) / size);
      const c = (a - 1) % size;
      const s = Math.floor((b - 1) / size);
      const d = (b - 1) % size;
      if (r === s || c === d || Math.abs(r - s) === Math.abs(c - d)) clauses.push([-a, -b]);
    }
  }
  return { variables, clauses };
}
export function pigeon(pigeons: number, holes: number): Formula {
  const clauses: number[][] = [];
  const variable = (i: number, j: number) => (i - 1) * holes + j;
  for (let i = 1; i <= pigeons; i++) {
    clauses.push(Array.from({ length: holes }, (_, j) => variable(i, j + 1)));
  }
  for (let i = 1; i <= pigeons; i++) {
    for (let a = 1; a <= holes; a++) {
      for (let b = a + 1; b <= holes; b++) clauses.push([-variable(i, a), -variable(i, b)]);
    }
  }
  for (let j = 1; j <= holes; j++) {
    for (let a = 1; a <= pigeons; a++) {
      for (let b = a + 1; b <= pigeons; b++) clauses.push([-variable(a, j), -variable(b, j)]);
    }
  }
  return { variables: pigeons * holes, clauses };
}
export function coloring(graph: Graph, colors: number): Formula {
  const clauses: number[][] = [];
  const variable = (v: number, c: number) => (v - 1) * colors + c;
  for (let v = 1; v <= graph.vertices; v++) {
    clauses.push(Array.from({ length: colors }, (_, c) => variable(v, c + 1)));
  }
  for (let v = 1; v <= graph.vertices; v++) {
    for (let a = 1; a <= colors; a++) {
      for (let b = a + 1; b <= colors; b++) clauses.push([-variable(v, a), -variable(v, b)]);
    }
  }
  for (const [a, b] of graph.edges) {
    for (let c = 1; c <= colors; c++) clauses.push([-variable(a, c), -variable(b, c)]);
  }
  return { variables: graph.vertices * colors, clauses };
}
export function positions(model: Model, rows: number, width: number): number[] {
  const result: number[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 1; c <= width; c++) {
      if (model[r * width + c]) {
        result.push(c);
        break;
      }
    }
  }
  return result;
}

import { mkdirSync, readFileSync } from 'node:fs';
import {
  InputError,
  wellFormedNumber,
  readDimacs,
  modelLines,
  type Formula,
  type Model,
} from './cnf_io.ts';
import { queens, pigeon, coloring, positions, type Graph } from './encoders.ts';
import { preprocess } from './preprocess.ts';
import { solveRound, type SearchStatistics } from './dpll.ts';
import {
  items,
  numberList,
  frequencyList,
  boardLines,
  writeParagraphs,
  writeCsv,
} from './report.ts';

type NumericArgument = 'size' | 'pigeons' | 'holes' | 'colors' | 'maximum' | 'limit';
type ArgumentKind = NumericArgument | 'file' | 'graph';
const ARGUMENTS = new Map<string, ArgumentKind[]>([
  ['SOLVE', ['file']],
  ['ENUM', ['file', 'limit']],
  ['CORE', ['file']],
  ['QUEENS', ['size', 'limit']],
  ['PIGEON', ['pigeons', 'holes', 'limit']],
  ['COLOR', ['graph', 'colors', 'limit']],
  ['CHROMATIC', ['graph', 'maximum']],
]);
const LIMITS: Record<NumericArgument, number> = {
  size: 8,
  pigeons: 8,
  holes: 8,
  colors: 6,
  maximum: 6,
  limit: 200,
};
const STAT_COLUMNS = [
  'job',
  'command',
  'status',
  'variables',
  'clauses',
  'removed_clauses',
  'decisions',
  'propagations',
  'conflicts',
  'max_depth',
  'models',
  'rounds',
];
interface Job {
  number: number;
  line: string;
  command: string;
  arguments: string[];
  file: string;
  graph?: Graph;
  size: number;
  pigeons: number;
  holes: number;
  colors: number;
  maximum: number;
  limit: number;
}
interface SolveResult {
  formula: Formula;
  preprocessing: ReturnType<typeof preprocess>;
  models: Model[];
  rounds: number;
  stop: 'preprocess' | 'all' | 'limit';
  status: 'SAT' | 'UNSAT';
  statistics: SearchStatistics;
  trace: string[];
  removed: number;
  attempts: { colors: number; result: SolveResult }[];
}
interface CompletedJob {
  job: Job;
  result: SolveResult;
  analysis: ReturnType<typeof analyzeModels>;
  core?: ReturnType<typeof unsatisfiableCore>;
}
function sum<T>(values: T[], select: (value: T) => number): number {
  let total = 0;
  for (const value of values) total += select(value);
  return total;
}
const emptyStatistics = (): SearchStatistics => ({
  decisions: 0,
  propagations: 0,
  conflicts: 0,
  maxDepth: 0,
});
function addStatistics(total: SearchStatistics, part: SearchStatistics): void {
  total.decisions += part.decisions;
  total.propagations += part.propagations;
  total.conflicts += part.conflicts;
  total.maxDepth = Math.max(total.maxDepth, part.maxDepth);
}
function analyzeGraph(graph: Graph): void {
  const adjacent: number[][] = Array.from({ length: graph.vertices + 1 }, () => []);
  for (const [a, b] of graph.edges) {
    adjacent[a].push(b);
    adjacent[b].push(a);
  }
  const order = Array.from({ length: graph.vertices }, (_, i) => i + 1).sort(
    (a, b) => adjacent[b].length - adjacent[a].length || a - b,
  );
  const colors: number[] = Array(graph.vertices + 1).fill(0);
  let maximumDegree = 0;
  let used = 0;
  for (const v of order) {
    maximumDegree = Math.max(maximumDegree, adjacent[v].length);
    const unavailable = new Set(adjacent[v].map((w) => colors[w]));
    let color = 1;
    while (unavailable.has(color)) color++;
    colors[v] = color;
    used = Math.max(used, color);
  }
  graph.maximumDegree = maximumDegree;
  graph.greedy = { used, colors: colors.slice(1) };
}
function readGraphs(): Map<string, Graph> {
  const graphs = new Map<string, Graph>();
  const lines = readFileSync('input/graphs.txt', 'ascii').split('\n');
  let graph: Graph | null = null;
  let seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (graph === null) {
      if (line === '' || line.startsWith('#')) continue;
      const [, name, vertices] = line.split(' ');
      graph = {
        name,
        vertices: Number(vertices),
        edges: [],
        reason: null,
        maximumDegree: 0,
        greedy: { used: 0, colors: [] },
      };
      graphs.set(name, graph);
      seen = new Set();
      continue;
    }
    if (line === 'END') {
      if (graph.reason === null) {
        graph.edges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        analyzeGraph(graph);
      }
      graph = null;
      continue;
    }
    if (graph.reason !== null) continue;
    const tokens = line.split(' ');
    let reason: string | null = null;
    if (tokens.length !== 2 || !tokens.every(wellFormedNumber)) reason = 'bad edge line';
    else {
      const a = Number(tokens[0]);
      const b = Number(tokens[1]);
      const edge: [number, number] = [Math.min(a, b), Math.max(a, b)];
      const key = edge.join(',');
      if (a < 1 || a > graph.vertices || b < 1 || b > graph.vertices) {
        reason = 'vertex out of range';
      } else if (a === b) reason = 'self loop';
      else if (seen.has(key)) reason = 'duplicate edge';
      else {
        graph.edges.push(edge);
        seen.add(key);
      }
    }
    if (reason !== null) graph.reason = `${reason} at line ${i + 1}`;
  }
  return graphs;
}
function readJobs(): Job[] {
  const jobs: Job[] = [];
  for (const line of readFileSync('input/jobs.txt', 'ascii').split('\n')) {
    if (line === '' || line.startsWith('#')) continue;
    const [command, ...args] = line.split(' ');
    jobs.push({
      number: jobs.length + 1,
      line,
      command,
      arguments: args,
      file: '',
      size: 0,
      pigeons: 0,
      holes: 0,
      colors: 0,
      maximum: 0,
      limit: 1,
    });
  }
  return jobs;
}
function validateJob(job: Job, graphs: Map<string, Graph>): void {
  const kinds = ARGUMENTS.get(job.command);
  if (kinds === undefined) throw new InputError(`unknown command ${job.command}`);
  if (job.arguments.length !== kinds.length) throw new InputError('wrong argument count');
  kinds.forEach((kind, i) => {
    const token = job.arguments[i];
    if (kind === 'file') {
      if (!/^[a-z0-9_]{1,20}\.cnf$/.test(token)) throw new InputError(`bad file name ${token}`);
      job.file = token;
    } else if (kind === 'graph') {
      const graph = graphs.get(token);
      if (graph === undefined) throw new InputError(`unknown graph ${token}`);
      if (graph.reason !== null) throw new InputError(`invalid graph ${token}: ${graph.reason}`);
      job.graph = graph;
    } else {
      if (!wellFormedNumber(token)) throw new InputError(`bad number ${token}`);
      const value = Number(token);
      if (value < 1 || value > LIMITS[kind]) throw new InputError(`out of range ${token}`);
      job[kind] = value;
    }
  });
}
function originalFormula(job: Job): Formula {
  if (job.file !== '') return readDimacs(`input/${job.file}`);
  if (job.command === 'QUEENS') return queens(job.size);
  if (job.command === 'PIGEON') return pigeon(job.pigeons, job.holes);
  return coloring(job.graph!, job.colors);
}
function solveFormula(formula: Formula, limit: number): SolveResult {
  const simplified = preprocess(formula, limit === 1);
  const result: SolveResult = {
    formula,
    preprocessing: simplified,
    models: [],
    rounds: 0,
    stop: 'limit',
    status: 'UNSAT',
    statistics: emptyStatistics(),
    trace: [],
    removed: simplified.removed,
    attempts: [],
  };
  if (simplified.emptyClause !== null) {
    result.stop = 'preprocess';
    return result;
  }
  const blocking: number[][] = [];
  while (result.models.length < limit) {
    const round = solveRound(formula.variables, [...simplified.clauses, ...blocking]);
    result.rounds++;
    if (result.rounds === 1) result.trace = round.events;
    addStatistics(result.statistics, round.statistics);
    if (!round.satisfiable) {
      result.stop = 'all';
      break;
    }
    const model: Model = Array(formula.variables + 1).fill(false);
    for (let x = 1; x <= formula.variables; x++) model[x] = simplified.fixed[x] ?? round.model![x];
    result.models.push(model);
    blocking.push(simplified.active.map((x) => (model[x] ? -x : x)));
  }
  if (result.models.length) result.status = 'SAT';
  return result;
}
function literalTrue(literal: number, model: Model, flipped = 0): boolean {
  const x = Math.abs(literal);
  const value = x === flipped ? !model[x] : model[x];
  return literal > 0 ? value : !value;
}
function analyzeModels(result: SolveResult) {
  const { formula, models } = result;
  if (models.length === 0) return null;
  let failure: { model: number; clause: number } | null = null;
  for (let i = 0; i < models.length && failure === null; i++) {
    for (let j = 0; j < formula.clauses.length; j++) {
      if (!formula.clauses[j].some((literal) => literalTrue(literal, models[i]))) {
        failure = { model: i + 1, clause: j + 1 };
        break;
      }
    }
  }
  const distribution = formula.clauses.map(
    (clause) => clause.filter((literal) => literalTrue(literal, models[0])).length,
  );
  const safe: number[] = [];
  for (let x = 1; x <= formula.variables; x++) {
    if (
      formula.clauses.every((clause) =>
        clause.some((literal) => literalTrue(literal, models[0], x)),
      )
    ) {
      safe.push(x);
    }
  }
  let diversity: { pairs: number; minimum: number; maximum: number } | null = null;
  if (models.length >= 2) {
    diversity = { pairs: 0, minimum: formula.variables, maximum: 0 };
    for (let i = 0; i < models.length; i++) {
      for (let j = i + 1; j < models.length; j++) {
        let distance = 0;
        for (let x = 1; x <= formula.variables; x++) if (models[i][x] !== models[j][x]) distance++;
        diversity.pairs++;
        diversity.minimum = Math.min(diversity.minimum, distance);
        diversity.maximum = Math.max(diversity.maximum, distance);
      }
    }
  }
  let backbone: number[] | null = null;
  if (result.stop === 'all') {
    backbone = [];
    for (let x = 1; x <= formula.variables; x++) {
      if (models.every((model) => model[x] === models[0][x])) backbone.push(models[0][x] ? x : -x);
    }
  }
  return { failure, distribution, safe, diversity, backbone };
}
function unsatisfiableCore(formula: Formula) {
  const retained = new Set(formula.clauses.map((_, i) => i + 1));
  let decisions = 0;
  let conflicts = 0;
  for (let number = 1; number <= formula.clauses.length; number++) {
    const clauses = formula.clauses.filter((_, i) => retained.has(i + 1) && i + 1 !== number);
    const result = solveFormula({ variables: formula.variables, clauses }, 1);
    decisions += result.statistics.decisions;
    conflicts += result.statistics.conflicts;
    if (result.status === 'UNSAT') retained.delete(number);
  }
  return { clauses: [...retained], decisions, conflicts };
}
function solveChromatic(job: Job): SolveResult {
  const attempts: SolveResult['attempts'] = [];
  const statistics = emptyStatistics();
  let rounds = 0;
  let removed = 0;
  for (let colors = 1; colors <= job.maximum; colors++) {
    const result = solveFormula(coloring(job.graph!, colors), 1);
    attempts.push({ colors, result });
    addStatistics(statistics, result.statistics);
    rounds += result.rounds;
    removed += result.removed;
    job.colors = colors;
    if (result.status === 'SAT') break;
  }
  return { ...attempts[attempts.length - 1].result, attempts, statistics, rounds, removed };
}
const heading = (job: Job): string => `JOB ${job.number} ${job.line}`;
const searchLine = (s: SearchStatistics): string =>
  items('search', {
    decisions: s.decisions,
    propagations: s.propagations,
    conflicts: s.conflicts,
    max_depth: s.maxDepth,
  });
const graphLine = (g: Graph): string =>
  items('graph', {
    vertices: g.vertices,
    edges: g.edges.length,
    max_degree: g.maximumDegree,
    greedy: g.greedy.used,
  });
function analysisLines(completed: CompletedJob, full = true): string[] {
  const { result, analysis: a } = completed;
  if (a === null) return [];
  const lines = [
    a.failure === null
      ? items('verify ok', {
          models: result.models.length,
          clauses: result.formula.clauses.length,
          true_literals: frequencyList(a.distribution),
        })
      : items('verify failed', a.failure),
    items('flips', { safe: a.safe.length, variables: numberList(a.safe) }),
  ];
  if (full && a.diversity !== null) {
    lines.push(
      items('diversity', {
        pairs: a.diversity.pairs,
        min_distance: a.diversity.minimum,
        max_distance: a.diversity.maximum,
      }),
    );
  }
  if (full && a.backbone !== null) {
    lines.push(items('backbone', { size: a.backbone.length, literals: numberList(a.backbone) }));
  }
  return lines;
}
function preprocessingLines(p: ReturnType<typeof preprocess>): string[] {
  const s = p.statistics;
  const r = p.records;
  const lines = [
    items('preprocess', {
      pure: p.pure ? 'on' : 'off',
      tautologies: s.tautologies,
      duplicate_literals: s.duplicateLiterals,
      unit_fixed: s.unitFixed,
      unit_removed: s.unitRemoved,
      subsumed: s.subsumed,
      pure_fixed: s.pureFixed,
      pure_removed: s.pureRemoved,
      removed: p.removed,
    }),
    items('removed_clauses', {
      tautology: numberList(r.tautology),
      unit: numberList(r.unit),
      subsumed: numberList(r.subsumed),
      pure: numberList(r.pure),
    }),
  ];
  if (p.emptyClause !== null) lines.push(items('simplified', { empty_clause: p.emptyClause }));
  else {
    const lengths = p.clauses.map((clause) => clause.length);
    lines.push(
      items('simplified', {
        clauses: p.clauses.length,
        literals: sum(lengths, (x) => x),
        lengths: frequencyList(lengths),
        fixed: p.fixedLiterals.length,
        active: p.active.length,
      }),
      items('fixed', { literals: numberList(p.fixedLiterals) }),
    );
  }
  return lines;
}
function jobParagraph(completed: CompletedJob): string[] {
  const { job, result: r } = completed;
  const lines = [heading(job)];
  if (job.command === 'CHROMATIC') {
    lines.push(graphLine(job.graph!));
    for (const attempt of r.attempts) {
      const a = attempt.result;
      const s = a.statistics;
      lines.push(
        items('attempt', {
          k: attempt.colors,
          clauses: a.formula.clauses.length,
          removed: a.removed,
          result: a.status,
          stop: a.stop,
          decisions: s.decisions,
          propagations: s.propagations,
          conflicts: s.conflicts,
          max_depth: s.maxDepth,
        }),
      );
    }
    lines.push(
      items(`result ${r.status}`, {
        chromatic: r.status === 'SAT' ? job.colors : '-',
        attempts: r.attempts.length,
      }),
      searchLine(r.statistics),
      ...analysisLines(completed, false),
    );
    return lines;
  }
  if (job.command === 'COLOR') lines.push(graphLine(job.graph!));
  const lengths = r.formula.clauses.map((clause) => clause.length);
  lines.push(
    items('formula', {
      variables: r.formula.variables,
      clauses: r.formula.clauses.length,
      literals: sum(lengths, (x) => x),
      lengths: frequencyList(lengths),
    }),
    ...preprocessingLines(r.preprocessing),
    items(`result ${r.status}`, { models: r.models.length, rounds: r.rounds, stop: r.stop }),
    searchLine(r.statistics),
  );
  if (r.rounds > 0) {
    lines.push(
      'trace ' +
        (r.trace.length ? r.trace.slice(0, 12).join(' ') : '-') +
        (r.trace.length > 12 ? ` +${r.trace.length - 12}` : ''),
    );
  }
  lines.push(...analysisLines(completed));
  if (completed.core) {
    const c = completed.core;
    lines.push(
      items('core', {
        size: c.clauses.length,
        decisions: c.decisions,
        conflicts: c.conflicts,
        clauses: numberList(c.clauses),
      }),
    );
  }
  return lines;
}
function summaryParagraph(jobs: Job[], valid: CompletedJob[]): string[] {
  const sat = valid.filter((c) => c.result.status === 'SAT').length;
  const lines = [
    items('SUMMARY', {
      jobs: jobs.length,
      sat,
      unsat: valid.length - sat,
      error: jobs.length - valid.length,
    }),
    items('totals', {
      models: sum(valid, (c) => c.result.models.length),
      rounds: sum(valid, (c) => c.result.rounds),
      decisions: sum(valid, (c) => c.result.statistics.decisions),
      propagations: sum(valid, (c) => c.result.statistics.propagations),
      conflicts: sum(valid, (c) => c.result.statistics.conflicts),
      removed_clauses: sum(valid, (c) => c.result.removed),
    }),
  ];
  for (const command of ARGUMENTS.keys()) {
    const group = valid.filter((c) => c.job.command === command);
    if (!group.length) continue;
    const sat = group.filter((c) => c.result.status === 'SAT').length;
    lines.push(
      items(`command ${command}`, {
        jobs: group.length,
        sat,
        unsat: group.length - sat,
        decisions: sum(group, (c) => c.result.statistics.decisions),
        propagations: sum(group, (c) => c.result.statistics.propagations),
        conflicts: sum(group, (c) => c.result.statistics.conflicts),
      }),
    );
  }
  const rankings: [string, keyof SearchStatistics, string][] = [
    ['hardest', 'conflicts', 'conflicts'],
    ['deepest', 'maxDepth', 'max_depth'],
    ['busiest', 'propagations', 'propagations'],
  ];
  if (valid.length) {
    for (const [label, field, output] of rankings) {
      let best = valid[0];
      for (const c of valid) {
        if (c.result.statistics[field] > best.result.statistics[field]) best = c;
      }
      lines.push(items(label, { job: best.job.number, [output]: best.result.statistics[field] }));
    }
  }
  return lines;
}
function modelParagraph(c: CompletedJob): string[] {
  const lines = [heading(c.job)];
  c.result.models.forEach((model, i) => lines.push(`model ${i + 1}`, ...modelLines(model)));
  return lines;
}
interface BoardClass {
  number: number;
  canonical: number[];
  first: number;
  found: number;
  orbit: number;
}
function queenCanonical(columns: number[]) {
  const n = columns.length;
  const transforms: number[][] = Array.from({ length: 8 }, () => Array(n).fill(0));
  for (let r = 1; r <= n; r++) {
    const c = columns[r - 1];
    const images = [
      [r, c],
      [c, n + 1 - r],
      [n + 1 - r, n + 1 - c],
      [n + 1 - c, r],
      [r, n + 1 - c],
      [n + 1 - r, c],
      [c, r],
      [n + 1 - c, n + 1 - r],
    ];
    images.forEach(([r, c], i) => {
      transforms[i][r - 1] = c;
    });
  }
  const compare = (a: number[], b: number[]) => {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] - b[i];
    return 0;
  };
  transforms.sort(compare);
  return { canonical: transforms[0], orbit: new Set(transforms.map((t) => t.join(','))).size };
}
function colorCanonical(colors: number[]): number[] {
  const mapping = new Map<number, number>();
  return colors.map((color) => {
    if (!mapping.has(color)) mapping.set(color, mapping.size + 1);
    return mapping.get(color)!;
  });
}
function boardParagraph(completed: CompletedJob): string[] {
  const { job: j, result: r } = completed;
  const lines: string[] = [];
  if (j.command === 'PIGEON') {
    lines.push(items('PIGEON', { job: j.number, pigeons: j.pigeons, holes: j.holes }));
    r.models.forEach((model, i) => {
      const holes = positions(model, j.pigeons, j.holes);
      const empty: number[] = [];
      for (let h = 1; h <= j.holes; h++) if (!holes.includes(h)) empty.push(h);
      lines.push(
        items(`assignment ${i + 1}`, { holes: numberList(holes), empty: numberList(empty) }),
      );
    });
    let expected = j.pigeons > j.holes ? 0 : 1;
    if (expected) for (let i = 0; i < j.pigeons; i++) expected *= j.holes - i;
    lines.push(items('summary', { assignments: r.models.length, stop: r.stop, expected }));
    return lines;
  }
  const isQueen = j.command === 'QUEENS';
  const graph = j.graph;
  const classes: BoardClass[] = [];
  const lookup = new Map<string, BoardClass>();
  if (isQueen) lines.push(items('QUEENS', { job: j.number, n: j.size }));
  else {
    lines.push(
      items(j.command, {
        job: j.number,
        graph: graph!.name,
        vertices: graph!.vertices,
        edges: graph!.edges.length,
        colors: j.colors,
      }),
      items('greedy', { used: graph!.greedy.used, colors: numberList(graph!.greedy.colors) }),
    );
  }
  r.models.forEach((model, i) => {
    const sequence = positions(
      model,
      isQueen ? j.size : graph!.vertices,
      isQueen ? j.size : j.colors,
    );
    const symmetry = isQueen
      ? queenCanonical(sequence)
      : { canonical: colorCanonical(sequence), orbit: 0 };
    const key = symmetry.canonical.join(',');
    let entry = lookup.get(key);
    if (entry === undefined) {
      entry = {
        number: classes.length + 1,
        canonical: symmetry.canonical,
        orbit: symmetry.orbit,
        first: i + 1,
        found: 0,
      };
      classes.push(entry);
      lookup.set(key, entry);
    }
    entry.found++;
    if (isQueen) {
      lines.push(
        items(`solution ${i + 1}`, { columns: numberList(sequence), class: entry.number }),
      );
      if (entry.first === i + 1) lines.push(...boardLines(sequence));
    } else {
      const sizes: number[] = Array(j.colors).fill(0);
      for (const color of sequence) sizes[color - 1]++;
      lines.push(
        items(`coloring ${i + 1}`, {
          colors: numberList(sequence),
          used: new Set(sequence).size,
          sizes: numberList(sizes),
          class: entry.number,
        }),
      );
    }
  });
  for (const c of classes) {
    lines.push(
      isQueen
        ? items(`class ${c.number}`, {
            orbit: c.orbit,
            found: c.found,
            first: c.first,
            canonical: numberList(c.canonical),
          })
        : items(`class ${c.number}`, {
            found: c.found,
            first: c.first,
            canonical: numberList(c.canonical),
          }),
    );
  }
  lines.push(
    items('summary', {
      [isQueen ? 'solutions' : 'colorings']: r.models.length,
      stop: r.stop,
      classes: classes.length,
    }),
  );
  return lines;
}
function statisticsValues(c: CompletedJob): (string | number)[] {
  const r = c.result;
  const s = r.statistics;
  return [
    c.job.number,
    c.job.command,
    r.status,
    r.formula.variables,
    r.formula.clauses.length,
    r.removed,
    s.decisions,
    s.propagations,
    s.conflicts,
    s.maxDepth,
    r.models.length,
    r.rounds,
  ];
}
function main(): void {
  const graphs = readGraphs();
  const jobs = readJobs();
  const valid: CompletedJob[] = [];
  const results: string[][] = [];
  for (const job of jobs) {
    try {
      validateJob(job, graphs);
      const result =
        job.command === 'CHROMATIC'
          ? solveChromatic(job)
          : solveFormula(originalFormula(job), job.limit);
      const completed: CompletedJob = { job, result, analysis: analyzeModels(result) };
      if (job.command === 'CORE' && result.status === 'UNSAT') {
        completed.core = unsatisfiableCore(result.formula);
      }
      valid.push(completed);
      results.push(jobParagraph(completed));
    } catch (error) {
      if (!(error instanceof InputError)) throw error;
      results.push([heading(job), `error ${error.message}`]);
    }
  }
  results.push(summaryParagraph(jobs, valid));
  mkdirSync('output', { recursive: true });
  writeParagraphs('results.txt', results);
  writeParagraphs(
    'models.txt',
    valid.filter((c) => c.result.models.length > 0).map(modelParagraph),
  );
  writeParagraphs(
    'boards.txt',
    valid
      .filter((c) => ['QUEENS', 'PIGEON', 'COLOR', 'CHROMATIC'].includes(c.job.command))
      .map(boardParagraph),
  );
  writeCsv('stats.csv', [STAT_COLUMNS, ...valid.map(statisticsValues)]);
}
main();

import type { Formula } from './cnf_io.ts';

interface Clause {
  number: number;
  literals: number[];
}
export function preprocess(formula: Formula, usePure: boolean) {
  const fixed: (boolean | null)[] = Array(formula.variables + 1).fill(null);
  const statistics = {
    tautologies: 0,
    duplicateLiterals: 0,
    unitFixed: 0,
    unitRemoved: 0,
    subsumed: 0,
    pureFixed: 0,
    pureRemoved: 0,
  };
  const records: Record<'tautology' | 'unit' | 'subsumed' | 'pure', number[]> = {
    tautology: [],
    unit: [],
    subsumed: [],
    pure: [],
  };
  let working: Clause[] = [];
  let emptyClause: number | null = null;
  formula.clauses.forEach((literals, i) => {
    const unique = new Set(literals);
    if (literals.some((literal) => unique.has(-literal))) {
      statistics.tautologies++;
      records.tautology.push(i + 1);
    } else {
      statistics.duplicateLiterals += literals.length - unique.size;
      working.push({ number: i + 1, literals: [...unique] });
    }
  });
  for (;;) {
    const empty = working.find((clause) => clause.literals.length === 0);
    if (empty !== undefined) {
      emptyClause = empty.number;
      break;
    }
    const unit = working.find((clause) => clause.literals.length === 1);
    if (unit === undefined) break;
    const literal = unit.literals[0];
    fixed[Math.abs(literal)] = literal > 0;
    statistics.unitFixed++;
    const remaining: Clause[] = [];
    for (const clause of working) {
      if (clause.literals.includes(literal)) {
        statistics.unitRemoved++;
        records.unit.push(clause.number);
      } else {
        remaining.push({
          number: clause.number,
          literals: clause.literals.filter((value) => value !== -literal),
        });
      }
    }
    working = remaining;
  }
  if (emptyClause === null) {
    const sets = working.map((clause) => new Set(clause.literals));
    const removed = working.map((clause, i) =>
      working.some(
        (candidate, j) =>
          j !== i &&
          (candidate.literals.length < clause.literals.length || j < i) &&
          candidate.literals.every((literal) => sets[i].has(literal)),
      ),
    );
    working = working.filter((clause, i) => {
      if (!removed[i]) return true;
      statistics.subsumed++;
      records.subsumed.push(clause.number);
      return false;
    });
    if (usePure) {
      for (;;) {
        const present = new Set(working.flatMap((clause) => clause.literals));
        const pure = new Set([...present].filter((literal) => !present.has(-literal)));
        if (pure.size === 0) break;
        for (const literal of pure) fixed[Math.abs(literal)] = literal > 0;
        statistics.pureFixed += pure.size;
        working = working.filter((clause) => {
          if (!clause.literals.some((literal) => pure.has(literal))) return true;
          statistics.pureRemoved++;
          records.pure.push(clause.number);
          return false;
        });
      }
    }
  }
  const active: number[] = [];
  const fixedLiterals: number[] = [];
  for (let x = 1; x <= formula.variables; x++) {
    if (fixed[x] === null) active.push(x);
    else fixedLiterals.push(fixed[x] ? x : -x);
  }
  for (const numbers of Object.values(records)) numbers.sort((a, b) => a - b);
  const removed =
    statistics.tautologies + statistics.unitRemoved + statistics.subsumed + statistics.pureRemoved;
  return {
    pure: usePure,
    fixed,
    fixedLiterals,
    active,
    clauses: working.map((clause) => clause.literals),
    statistics,
    records,
    removed,
    emptyClause,
  };
}

import { writeFileSync } from 'node:fs';

export function items(prefix: string, values: Record<string, string | number>): string {
  return (
    prefix +
    ' ' +
    Object.entries(values)
      .map(([name, value]) => `${name}=${value}`)
      .join(' ')
  );
}
export function numberList(values: number[]): string {
  return values.length ? values.join(',') : '-';
}
export function frequencyList(values: number[]): string {
  const counts = new Map<number, number>();
  for (const value of values) counts.set(value, (counts.get(value) ?? 0) + 1);
  return counts.size
    ? [...counts]
        .sort((a, b) => a[0] - b[0])
        .map(([value, count]) => `${value}:${count}`)
        .join(',')
    : '-';
}
export function boardLines(columns: number[]): string[] {
  return columns.map((c) => '.'.repeat(c - 1) + 'Q' + '.'.repeat(columns.length - c));
}
export function writeParagraphs(filename: string, paragraphs: string[][]): void {
  writeFileSync(
    `output/${filename}`,
    paragraphs.length ? paragraphs.map((lines) => lines.join('\n')).join('\n\n') + '\n' : '',
    'ascii',
  );
}
export function writeCsv(filename: string, rows: (string | number)[][]): void {
  writeFileSync(`output/${filename}`, rows.map((row) => row.join(',')).join('\n') + '\n', 'ascii');
}
